import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define BLOCK_THREADS 256
#define TILE_H 16
#define TILE_W 16
#define IC_CHUNK 8
// Tiled direct convolution kernel (structural rewrite).
// One block computes a TILE_H x TILE_W output tile for one (batch, output-channel).
// The input halo tile is staged cooperatively in shared memory in chunks of
// IC_CHUNK input channels, and the full weight for this output channel is
// staged once in shared memory. Each thread owns one output pixel of the tile.
__global__ void conv2d_direct_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch, int in_ch, int out_ch,
    int H, int W, int H_out, int W_out,
    int kh, int kw,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int stride_h, int stride_w)
{
    // Halo size of the input region needed for this output tile.
    const int halo_h = (TILE_H - 1) * stride_h + (kh - 1) * dil_h + 1;
    const int halo_w = (TILE_W - 1) * stride_w + (kw - 1) * dil_w + 1;
    extern __shared__ float smem[];
    float* s_input  = smem;                              // IC_CHUNK * halo_h * halo_w
    float* s_weight = smem + IC_CHUNK * halo_h * halo_w; // in_ch * kh * kw
    const int oc = blockIdx.y;
    const int b  = blockIdx.z;
    // Stage this output channel's weights into shared memory (all input channels).
    const int wcount = in_ch * kh * kw;
    const float* wbase = weight + (long)oc * wcount;
    for (int i = threadIdx.x; i < wcount; i += blockDim.x) {
        s_weight[i] = wbase[i];
    }
    // Output tile origin.
    const int tiles_x = (W_out + TILE_W - 1) / TILE_W;
    const int tile    = blockIdx.x;
    const int th0     = (tile / tiles_x) * TILE_H;
    const int tw0     = (tile % tiles_x) * TILE_W;
    // Input halo origin (may be negative due to padding).
    const int h0 = th0 * stride_h - pad_h;
    const int w0 = tw0 * stride_w - pad_w;
    const float* in_base = input + (long)b * in_ch * H * W;
    // Each thread owns one output pixel in the tile (BLOCK_THREADS == TILE_H*TILE_W).
    const int ty = threadIdx.x / TILE_W;
    const int tx = threadIdx.x % TILE_W;
    const int h_out = th0 + ty;
    const int w_out = tw0 + tx;
    const bool valid = (h_out < H_out) && (w_out < W_out);
    float sum = 0.0f;
    for (int ic0 = 0; ic0 < in_ch; ic0 += IC_CHUNK) {
        const int icn = min(IC_CHUNK, in_ch - ic0);
        const int tile_elems = icn * halo_h * halo_w;
        __syncthreads();
        // Cooperatively stage the input halo tile for icn channels (zero-fill padding).
        for (int i = threadIdx.x; i < tile_elems; i += blockDim.x) {
            const int c  = i / (halo_h * halo_w);
            const int r  = (i / halo_w) % halo_h;
            const int cc = i % halo_w;
            const int h_in = h0 + r;
            const int w_in = w0 + cc;
            float v = 0.0f;
            if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                v = in_base[((long)(ic0 + c) * H + h_in) * W + w_in];
            }
            s_input[i] = v;
        }
        __syncthreads();
        // Accumulate this chunk's contribution from shared memory.
        for (int c = 0; c < icn; c++) {
            const float* s_in_c = s_input + c * halo_h * halo_w;
            const float* w_ic   = s_weight + (ic0 + c) * kh * kw;
            #pragma unroll
            for (int i = 0; i < kh; i++) {
                const int r = ty * stride_h + i * dil_h;
                const float* s_row = s_in_c + r * halo_w;
                const float* w_row = w_ic + i * kw;
                #pragma unroll
                for (int j = 0; j < kw; j++) {
                    sum += s_row[tx * stride_w + j * dil_w] * w_row[j];
                }
            }
        }
    }
    if (valid) {
        output[(((long)b * out_ch + oc) * H_out + h_out) * W_out + w_out] = sum;
    }
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight,
                             int64_t stride_h, int64_t stride_w,
                             int64_t pad_h, int64_t pad_w,
                             int64_t dil_h, int64_t dil_w) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
                weight.scalar_type() == torch::kFloat32, "float32 required");
    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();
    const int batch  = input_c.size(0);
    const int in_ch  = input_c.size(1);
    const int H      = input_c.size(2);
    const int W      = input_c.size(3);
    const int out_ch = weight_c.size(0);
    const int kh     = weight_c.size(2);
    const int kw     = weight_c.size(3);
    const int H_out = (H + 2 * (int)pad_h - (int)dil_h * (kh - 1) - 1) / (int)stride_h + 1;
    const int W_out = (W + 2 * (int)pad_w - (int)dil_w * (kw - 1) - 1) / (int)stride_w + 1;
    auto output = torch::empty({batch, out_ch, H_out, W_out}, input_c.options());
    const int wcount = in_ch * kh * kw;
    const int halo_h = (TILE_H - 1) * (int)stride_h + (kh - 1) * (int)dil_h + 1;
    const int halo_w = (TILE_W - 1) * (int)stride_w + (kw - 1) * (int)dil_w + 1;
    const size_t shmem = ((size_t)IC_CHUNK * halo_h * halo_w + (size_t)wcount) * sizeof(float);
    TORCH_CHECK(shmem <= 96 * 1024, "tile too large for shared memory");
    const int tiles_x = (W_out + TILE_W - 1) / TILE_W;
    const int tiles_y = (H_out + TILE_H - 1) / TILE_H;
    dim3 grid(tiles_x * tiles_y, out_ch, batch);
    dim3 block(BLOCK_THREADS);
    if (shmem > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_direct_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)shmem);
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv2d_direct_kernel<<<grid, block, shmem, stream>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, in_ch, out_ch, H, W, H_out, W_out,
        kh, kw,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        (int)stride_h, (int)stride_w);
    return output;
}
'''

cpp_source = "torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, int64_t stride_h, int64_t stride_w, int64_t pad_h, int64_t pad_w, int64_t dil_h, int64_t dil_w);"

conv2d_module = load_inline(
    name="conv2d_custom_direct",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["conv2d_forward"],
    verbose=False,
)


def _pair(x):
    if isinstance(x, tuple):
        return x
    return (x, x)


class ModelNew(nn.Module):
    """
    2D convolution implemented with a custom CUDA kernel.

    The nn.Conv2d submodule is kept only as a parameter holder so that
    initialization and state_dict layout match the reference Model exactly;
    all computation in forward() is performed by the custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                stride=stride, padding=padding,
                                dilation=dilation, bias=bias)
        self.stride = _pair(stride)
        self.padding = _pair(padding)
        self.dilation = _pair(dilation)
        self.has_bias = bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv2d.weight
        if (x.is_cuda and x.dtype == torch.float32 and not self.has_bias):
            return conv2d_module.conv2d_forward(
                x, weight,
                self.stride[0], self.stride[1],
                self.padding[0], self.padding[1],
                self.dilation[0], self.dilation[1])
        # Fallback for non-CUDA / non-float32 / biased configurations.
        return F.conv2d(x, weight, self.conv2d.bias, self.stride,
                        self.padding, self.dilation)

