// One block handles one (batch, output-channel) pair.
// The weights for that output channel are staged in shared memory,
// and threads iterate over the output pixels with a grid-stride loop.
__global__ void conv2d_direct_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch, int in_ch, int out_ch,
    int H, int W, int H_out, int W_out,
    int kh, int kw,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int stride_h, int stride_w)
{
    extern __shared__ float s_weight[];

    const int oc = blockIdx.y;
    const int b  = blockIdx.x;

    // Stage this output channel's weights into shared memory.
    const int wcount = in_ch * kh * kw;
    const float* wbase = weight + (long)oc * wcount;
    for (int i = threadIdx.x; i < wcount; i += blockDim.x) {
        s_weight[i] = wbase[i];
    }
    __syncthreads();

    const int HW = H_out * W_out;
    const float* in_base  = input + (long)b * in_ch * H * W;
    float* out_base = output + ((long)b * out_ch + oc) * HW;

    for (int idx = threadIdx.x; idx < HW; idx += blockDim.x) {
        const int h_out = idx / W_out;
        const int w_out = idx % W_out;

        float sum = 0.0f;
        for (int ic = 0; ic < in_ch; ic++) {
            const float* in_ic = in_base + (long)ic * H * W;
            const float* w_ic  = s_weight + ic * kh * kw;
