                if (h_in < 0 || h_in >= H) continue;
                const float* in_row = in_ic + (long)h_in * W;
                const float* w_row  = w_ic + i * kw;
                #pragma unroll
                for (int j = 0; j < kw; j++) {
                    const int w_in = w_out * stride_w + j * dil_w - pad_w;
                    if (w_in < 0 || w_in >= W) continue;
                    sum += in_row[w_in] * w_row[j];
                }
            }
        }
        out_base[idx] = sum;
    }
